using Godot;
using System;
public partial class ImageWorkspaceOperations
{
    public void start_macro(Control owner){owner.Get("_macro_buffer").AsGodotArray().Clear();owner.Set("_macro_recording",true);owner.Get("status").As<Label>().Text="Macro recording started · use Ctrl+K to run actions";}
    public void stop_macro(Control owner)
    {
        if(!owner.Get("_macro_recording").AsBool())return;owner.Set("_macro_recording",false);var dialog=new ConfirmationDialog{Title="Save macro"};owner.AddChild(dialog);var macros=owner.Get("_macros").AsGodotDictionary();var input=new LineEdit{Text="Macro "+(macros.Count+1),CustomMinimumSize=new Vector2(320,0)};dialog.AddChild(input);dialog.Confirmed+=()=>{if(input.Text.Trim().Length>0){macros[input.Text.Trim()]=owner.Get("_macro_buffer").AsGodotArray().Duplicate();dialog.QueueFree();}};dialog.Canceled+=dialog.QueueFree;dialog.PopupCentered();input.GrabFocus();input.SelectAll();
    }
    public void run_macro(Control owner,string name){bool recording=owner.Get("_macro_recording").AsBool();owner.Set("_macro_recording",false);try{foreach(var command in Get(owner.Get("_macros").AsGodotDictionary(),name,new Godot.Collections.Array()).AsGodotArray())run_named_command(owner,command.AsString());}finally{owner.Set("_macro_recording",recording);}owner.Get("status").As<Label>().Text="Ran macro · "+name;}
    public void automation_panel(Control owner)
    {
        var ui=workflow_window(owner,"Macros & batch actions",new Vector2(700,480));var popup=ui["popup"].As<PopupPanel>();var body=ui["body"].As<VBoxContainer>();var recording=panel_card(body,"Command macro","Record actions launched from the command palette, then replay them in one click.");var row=new HFlowContainer();recording.AddChild(row);bool active=owner.Get("_macro_recording").AsBool();button(owner,row,active?"Stop & save…":"● Start recording",Callable.From(()=>{if(active)stop_macro(owner);else start_macro(owner);}),"","");button(owner,row,"Customize hotkeys…",Callable.From(()=>customize_shortcuts(owner)),"","");if(active){var state=new Label{Text="Recording "+owner.Get("_macro_buffer").AsGodotArray().Count+" command(s)"};state.AddThemeColorOverride("font_color",new Color("ff9f7b"));recording.AddChild(state);}var list=panel_card(body,"Saved macros","");var macros=owner.Get("_macros").AsGodotDictionary();foreach(var key in macros.Keys){string name=key.AsString();var macroRow=new HBoxContainer();list.AddChild(macroRow);macroRow.AddChild(new Label{Text=name+"  ·  "+macros[name].AsGodotArray().Count+" actions",SizeFlagsHorizontal=Control.SizeFlags.ExpandFill});button(owner,macroRow,"Run",Callable.From(()=>run_macro(owner,name)),"","");button(owner,macroRow,"×",Callable.From(()=>{macros.Remove(name);popup.QueueFree();automation_panel(owner);}),"","");}var batch=panel_card(body,"Batch shortcuts","Fast operations for every selected or top-level layer.");var actions=new HFlowContainer();batch.AddChild(actions);button(owner,actions,"Export top-level layers…",new Callable(owner,"_export_layers"),"","");button(owner,actions,"Rasterize selected",new Callable(owner,"rasterize_selected"),"","");button(owner,actions,"Duplicate selected",Callable.From(()=>duplicate_layers(owner)),"","");popup.PopupCentered();
    }
    public void customize_shortcuts(Control owner)
    {
        var dialog=new ConfirmationDialog{Title="Custom command hotkey"};owner.AddChild(dialog);var column=new VBoxContainer{CustomMinimumSize=new Vector2(470,180)};column.AddThemeConstantOverride("separation",8);dialog.AddChild(column);var command=new OptionButton();var commands=owner.Get("_commands").AsGodotArray();foreach(var value in commands)command.AddItem(value.AsGodotDictionary()["name"].AsString());column.AddChild(command);var capture=new LineEdit{PlaceholderText="Click here, then press the shortcut",Editable=false};column.AddChild(capture);string chosen="";capture.GuiInput+=input=>{if(input is InputEventKey key&&key.Pressed){chosen=shortcut_string(key);capture.Text=chosen;capture.AcceptEvent();}};var clear=new CheckButton{Text="Remove the custom shortcut for this command"};column.AddChild(clear);dialog.Confirmed+=()=>{string name=commands[command.Selected].AsGodotDictionary()["name"].AsString();var shortcuts=owner.Get("_custom_shortcuts").AsGodotDictionary();if(clear.ButtonPressed)shortcuts.Remove(name);else if(chosen.Length>0)shortcuts[name]=chosen;owner.Get("status").As<Label>().Text="Shortcut updated";dialog.QueueFree();};dialog.Canceled+=dialog.QueueFree;dialog.PopupCentered();capture.GrabFocus();
    }
}
